SELECT event, hour_of_day, COUNT(*) AS `count` FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' GROUP BY JSON_VALUE(data, '$.commit.collection') AS event, DateTime::GetHour(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) AS hour_of_day HAVING event IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') ORDER BY hour_of_day, event;
SELECT event, hour_of_day, COUNT(*) AS `count` FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' AND JSON_VALUE(data, '$.commit.collection') IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY JSON_VALUE(data, '$.commit.collection') AS event, (JSON_VALUE(data, '$.time_us' RETURNING Uint64) / 3600000000) % 24 AS hour_of_day ORDER BY hour_of_day, event;
SELECT event, hour_of_day, COUNT(*) AS `count` FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' AND (JSON_VALUE(data, '$.commit.collection') = 'app.bsky.feed.post' OR JSON_VALUE(data, '$.commit.collection') = 'app.bsky.feed.repost' OR JSON_VALUE(data, '$.commit.collection') = 'app.bsky.feed.like') GROUP BY JSON_VALUE(data, '$.commit.collection') AS event, DateTime::GetHour(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) AS hour_of_day ORDER BY hour_of_day, event;
SELECT event, hour_of_day, COUNT(*) AS `count` FROM (SELECT JSON_VALUE(data, '$.commit.collection') AS event, DateTime::GetHour(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) AS hour_of_day FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create') WHERE event IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT event, COUNT(*) AS `count` FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' AND JSON_VALUE(data, '$.commit.collection') IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY JSON_VALUE(data, '$.commit.collection') AS event ORDER BY event;
SELECT event, hour_of_day, COUNT(*) AS `count` FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' GROUP BY JSON_VALUE(data, '$.commit.collection') AS event, DateTime::GetHour(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) AS hour_of_day ORDER BY hour_of_day, event;
